import type { System } from '../../Engine/System';
import type { World } from '../../Engine/World';
import type { Boss } from '../Entity/Boss';
import type { TurretData } from '../Entity/TurretData';
import type { Plane } from '../Entity/Plane';
import type { TurretScheduleState } from '../Entity/TurretSchedule';
import type { BulletFireRequest } from './BulletSpawnSystem';
import { BATTLE_EVENT } from '../BattleEvents';

export class TurretSystem implements System {

    onTick(world: World, dt: number): void {
        for (const boss of world.query<Boss>('boss')) {
            if (boss.hp <= 0) continue;
            for (const turret of boss.turrets) {
                this._tickAim(world, boss, turret, dt);
            }
            this._tickFiring(world, boss, dt);
        }
    }

    // ===== 瞄准 =====
    private _tickAim(world: World, boss: Boss, turret: TurretData, dt: number): void {
        const c = turret.config;
        switch (c.aimMode) {
            case 'fixed':
                turret.aimAngle = c.baseAngle;
                break;
            case 'target':
                this._aimAtPlayer(world, boss, turret, dt);
                break;
            case 'spin':
                turret.aimAngle = (turret.aimAngle + c.aimSpeed * dt) % 360;
                break;
            case 'oscillate':
                turret.oscPhase += (c.aimSpeed * Math.PI / 180) * dt;
                turret.aimAngle = c.baseAngle
                    + Math.sin(turret.oscPhase) * c.oscRange;
                break;
        }
    }

    private _aimAtPlayer(world: World, boss: Boss, turret: TurretData, dt: number): void {
        const player = this._findPlayer(world);
        if (!player) return;

        const c = turret.config;
        const turretX = boss.x + c.offsetX;
        const turretY = boss.y + c.offsetY;

        const targetAngle = Math.atan2(player.y - turretY, player.x - turretX)
            * 180 / Math.PI;

        // 平滑旋转：diff 归一到 [-180, 180]，每帧最多转 aimSpeed * dt
        let diff = targetAngle - turret.aimAngle;
        diff = ((diff + 180) % 360 + 360) % 360 - 180;

        const maxStep = c.aimSpeed * dt;
        if (Math.abs(diff) <= maxStep) {
            turret.aimAngle = targetAngle;
        } else {
            turret.aimAngle += Math.sign(diff) * maxStep;
        }
    }

    private _findPlayer(world: World): Plane | null {
        for (const p of world.query<Plane>('player')) return p;
        return null;
    }

    // ===== 开火 =====

    private _tickFiring(world: World, boss: Boss, dt: number): void {
        const schedule = boss.turretSchedule;

        // 没有 schedule 配置 → 默认 volley（各自独立计时，当前行为）
        if (!schedule || schedule.config.mode === 'volley') {
            for (const turret of boss.turrets) {
                this._tickFire(world, boss, turret, dt);
            }
            return;
        }

        // sequence 模式
        this._tickSequence(world, boss, schedule, dt);
    }


    private _tickSequence(
    world: World,
    boss: Boss,
    s: TurretScheduleState,
    dt: number,
    ): void {
        // 已结束（loop = false 打完一圈）
        if (s.activeIndex < 0) return;

        // 喘息中：所有炮台停火
        if (s.gapTimer > 0) {
            s.gapTimer -= dt;
            if (s.gapTimer <= 0) {
                s.gapTimer = 0;
                s.burstElapsed = 0;
            }
            return;
        }

        const turret = boss.turrets[s.activeIndex];
        if (!turret) return;

        // 当前炮台开火
        this._tickFire(world, boss, turret, dt);

        // 累积持续时间
        s.burstElapsed += dt;
        const burstDuration = s.config.burstDuration ?? 2;
        if (s.burstElapsed >= burstDuration) {
            this._advanceTurret(boss, s);
        }
    }

    private _advanceTurret(boss: Boss, s: TurretScheduleState): void {
        s.activeIndex++;

        if (s.activeIndex >= boss.turrets.length) {
            if (s.config.loop ?? true) {
                s.activeIndex = 0;
            } else {
                // 打完一圈，结束
                s.activeIndex = -1;
                s.burstElapsed = 0;
                s.gapTimer = 0;
                return;
            }
        }

        // 新炮台冷却归零，避免切过去立刻开火
        const next = boss.turrets[s.activeIndex];
        if (next) next.cooldownTimer = 0;

        s.gapTimer = s.config.burstGap ?? 1;
        s.burstElapsed = 0;
    }

    private _tickFire(world: World, boss: Boss, turret: TurretData, dt: number): void {
        const c = turret.config;
        turret.cooldownTimer += dt;

        let guard = 0;
        while (turret.cooldownTimer >= c.fireInterval && guard++ < 16) {
            turret.cooldownTimer -= c.fireInterval;
            this._emitFire(world, boss, turret);
        }
    }

    private _emitFire(world: World, boss: Boss, turret: TurretData): void {
        const c = turret.config;
        const rad = turret.aimAngle * Math.PI / 180;

        const req: BulletFireRequest = {
            x: boss.x + c.offsetX,
            y: boss.y + c.offsetY,
            dirX: Math.cos(rad),
            dirY: Math.sin(rad),
            bulletSpeed: c.bulletSpeed,
            bulletDamage: c.bulletDamage,
            isPlayerBullet: false,
            spreadCount: c.spreadCount,
            spreadAngle: c.spreadAngle,
        };
        world.bus.emit(BATTLE_EVENT.WEAPON_FIRE, req);
    }




}